// ============================================
// Vite dev-server plugin — FlightOps writeback
// ============================================
// Exposes two POST endpoints during `npm run dev`, mirroring PostalOps'
// vite-plugin-csv-writeback.js:
//
//   POST /api/ontology-writeback
//     Persists the SIX artifacts produced by the OntologyEngine pipeline into
//     src/data/01..06*.json — the exact files Explorer and Chat import. This is
//     the last mile that makes the app's semantic layer "strictly based on the
//     artifacts generated by the OntologyEngine" rather than hand-authored JSON.
//
//   POST /api/writeback
//     Persists an approved recovery action: appends to
//     src/data/csv/action_execution_log.csv and applies flight/airport field
//     updates to both the CSV mirror and the data/*.json the Knowledge Graph
//     actually reads on page load.
//
// Both endpoints invalidate the affected modules in Vite's module graph so a
// reload picks up the new content instead of a cached import.

import fs from 'fs';
import path from 'path';

// Artifact key -> destination filename under src/data/
const ONTOLOGY_ARTIFACTS = {
  controlledVocab: '01_controlled_vocabulary.json',
  metadataStandard: '02_metadata_standard.json',
  taxonomy: '03_taxonomy.json',
  thesaurus: '04_thesaurus.json',
  ontology: '05_ontology.json',
  knowledgeGraph: '06_knowledge_graph.json',
};

const ACTION_LOG_HEADER =
  'execution_id,action_name,parameters_json,proposed_by,approved_by,status,proposed_ts,decided_ts,executed_ts,target_system_ack,sensitivity_marking,result_summary';

function readJsonBody(req) {
  return new Promise((resolve, reject) => {
    let body = '';
    req.on('data', (chunk) => {
      body += chunk;
      if (body.length > 25 * 1024 * 1024) reject(new Error('Payload too large'));
    });
    req.on('end', () => {
      try {
        resolve(JSON.parse(body || '{}'));
      } catch (err) {
        reject(new Error(`Malformed JSON body: ${err.message}`));
      }
    });
    req.on('error', reject);
  });
}

function csvEscape(value) {
  const s = value === null || value === undefined ? '' : String(value);
  return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
}

export default function flightOpsWritebackPlugin() {
  let projectRoot = '';

  return {
    name: 'flightops-writeback',

    configResolved(config) {
      projectRoot = config.root;
    },

    configureServer(server) {
      const invalidate = (filePath) => {
        const mods = server.moduleGraph.getModulesByFile(filePath);
        if (mods) mods.forEach((m) => server.moduleGraph.invalidateModule(m));
      };

      // ─── OntologyEngine artifacts → src/data/0*.json ────────────────────
      server.middlewares.use('/api/ontology-writeback', (req, res) => {
        res.setHeader('Content-Type', 'application/json');

        if (req.method !== 'POST') {
          res.statusCode = 405;
          res.end(JSON.stringify({ error: 'Method not allowed' }));
          return;
        }

        readJsonBody(req)
          .then((payload) => {
            const dataDir = path.join(projectRoot, 'src', 'data');
            if (!fs.existsSync(dataDir)) fs.mkdirSync(dataDir, { recursive: true });

            const written = [];
            const skipped = [];

            for (const [key, filename] of Object.entries(ONTOLOGY_ARTIFACTS)) {
              const value = payload[key];

              // An artifact is only written when the engine actually produced it.
              // Empty arrays / null are skipped so a partial run can never blank
              // out a good file that a previous run wrote.
              const isEmpty =
                value === null ||
                value === undefined ||
                (Array.isArray(value) && value.length === 0) ||
                (!Array.isArray(value) && typeof value === 'object' && Object.keys(value).length === 0);

              if (isEmpty) {
                skipped.push({ file: filename, reason: 'empty or missing in payload' });
                continue;
              }

              const target = path.join(dataDir, filename);
              fs.writeFileSync(target, `${JSON.stringify(value, null, 2)}\n`, 'utf8');
              invalidate(target);
              written.push({
                file: filename,
                bytes: fs.statSync(target).size,
                entries: Array.isArray(value) ? value.length : undefined,
              });
            }

            if (written.length === 0) {
              res.statusCode = 400;
              res.end(JSON.stringify({ error: 'No artifacts in payload — nothing written.', skipped }));
              return;
            }

            // Provenance sidecar: which corpus produced the artifacts now on disk.
            const provenance = {
              publishedAt: new Date().toISOString(),
              outputBase: payload.outputBase || null,
              sourceFiles: payload.sourceFiles || [],
              runMeta: payload.runMeta || null,
              artifacts: written.map((w) => w.file),
            };
            const provPath = path.join(dataDir, '00_provenance.json');
            fs.writeFileSync(provPath, `${JSON.stringify(provenance, null, 2)}\n`, 'utf8');
            invalidate(provPath);

            // eslint-disable-next-line no-console
            console.log(`[flightops-writeback] published ${written.length} ontology artifact(s) to src/data/`);
            res.end(JSON.stringify({ success: true, written, skipped, provenance }));
          })
          .catch((err) => {
            // eslint-disable-next-line no-console
            console.error('[flightops-writeback] ontology error:', err);
            res.statusCode = 500;
            res.end(JSON.stringify({ error: err.message }));
          });
      });

      // ─── Approved recovery action → action log + flight/airport state ───
      server.middlewares.use('/api/writeback', (req, res) => {
        res.setHeader('Content-Type', 'application/json');

        if (req.method !== 'POST') {
          res.statusCode = 405;
          res.end(JSON.stringify({ error: 'Method not allowed' }));
          return;
        }

        readJsonBody(req)
          .then((payload) => {
            const csvDir = path.join(projectRoot, 'src', 'data', 'csv');
            if (!fs.existsSync(csvDir)) fs.mkdirSync(csvDir, { recursive: true });
            const results = [];

            // 1. Append the governance record to action_execution_log.csv.
            if (payload.actionLog) {
              const logPath = path.join(csvDir, 'action_execution_log.csv');
              const row = payload.actionLog;

              if (!fs.existsSync(logPath)) {
                fs.writeFileSync(logPath, `${ACTION_LOG_HEADER}\n`, 'utf8');
              }

              const line = [
                row.execution_id,
                row.action_name,
                row.parameters_json,
                row.proposed_by,
                row.approved_by,
                row.status,
                row.proposed_ts,
                row.decided_ts,
                row.executed_ts,
                row.target_system_ack,
                row.sensitivity_marking,
                row.result_summary,
              ]
                .map(csvEscape)
                .join(',');

              const existing = fs.readFileSync(logPath, 'utf8');
              const sep = existing.endsWith('\n') ? '' : '\n';
              fs.appendFileSync(logPath, `${sep}${line}\n`, 'utf8');
              results.push({ file: 'action_execution_log.csv', action: 'appended', id: row.execution_id });
            }

            // 2. Rebook / re-tier at-risk flights in flight.csv + data/flights.json.
            if (payload.flightUpdates && payload.flightUpdates.length > 0) {
              const flightCsv = path.join(csvDir, 'flight.csv');
              if (fs.existsSync(flightCsv)) {
                const lines = fs.readFileSync(flightCsv, 'utf8').split('\n');
                const cols = lines[0].split(',');
                const idIdx = cols.indexOf('flight_id');
                const statusIdx = cols.indexOf('status');
                const tierIdx = cols.indexOf('connection_risk_tier');
                const delayIdx = cols.indexOf('delay_min');
                let updated = 0;

                for (const upd of payload.flightUpdates) {
                  for (let i = 1; i < lines.length; i++) {
                    if (!lines[i].trim()) continue;
                    const fields = lines[i].split(',');
                    if (fields[idIdx] !== upd.flightId) continue;
                    if (upd.newStatus !== undefined && statusIdx >= 0) fields[statusIdx] = upd.newStatus;
                    if (upd.newRiskTier !== undefined && tierIdx >= 0) fields[tierIdx] = upd.newRiskTier;
                    if (upd.newDelayMinutes !== undefined && delayIdx >= 0) fields[delayIdx] = String(upd.newDelayMinutes);
                    lines[i] = fields.join(',');
                    updated++;
                  }
                }
                fs.writeFileSync(flightCsv, lines.join('\n'), 'utf8');
                results.push({ file: 'flight.csv', action: 'updated', count: updated });
              }

              // The Knowledge Graph loads data/flights.json, not the CSV mirror.
              const flightsJsonPath = path.join(projectRoot, 'data', 'flights.json');
              try {
                const flights = JSON.parse(fs.readFileSync(flightsJsonPath, 'utf8'));
                for (const upd of payload.flightUpdates) {
                  const flight = flights.find((f) => f.flightId === upd.flightId);
                  if (!flight) continue;
                  if (upd.newStatus !== undefined) flight.status = upd.newStatus;
                  if (upd.newRiskTier !== undefined) flight.connectionRiskTier = upd.newRiskTier;
                  if (upd.newDelayMinutes !== undefined) flight.delayMinutes = upd.newDelayMinutes;
                  if (upd.rebookedOntoFlightId !== undefined) flight.rebookedOntoFlightId = upd.rebookedOntoFlightId;
                }
                fs.writeFileSync(flightsJsonPath, `${JSON.stringify(flights, null, 2)}\n`, 'utf8');
                invalidate(flightsJsonPath);
                results.push({ file: 'flights.json', action: 'updated', flights: payload.flightUpdates.map((u) => u.flightId) });
              } catch (err) {
                results.push({ file: 'flights.json', action: 'error', error: err.message });
              }
            }

            // 3. Gate-capacity reallocation in airport.csv + data/airports.json.
            if (payload.airportUpdates && payload.airportUpdates.length > 0) {
              const airportCsv = path.join(csvDir, 'airport.csv');
              if (fs.existsSync(airportCsv)) {
                const lines = fs.readFileSync(airportCsv, 'utf8').split('\n');
                const cols = lines[0].split(',');
                const idIdx = cols.indexOf('airport_id');
                const utilIdx = cols.indexOf('utilization_pct');
                const throughputIdx = cols.indexOf('current_throughput_hr');
                const statusIdx = cols.indexOf('status');
                const freeGatesIdx = cols.indexOf('free_gates');

                for (const upd of payload.airportUpdates) {
                  for (let i = 1; i < lines.length; i++) {
                    if (!lines[i].trim()) continue;
                    const fields = lines[i].split(',');
                    if (fields[idIdx] !== upd.airportId) continue;
                    if (upd.newUtilizationPct !== undefined && utilIdx >= 0) fields[utilIdx] = String(upd.newUtilizationPct);
                    if (upd.newThroughputPerHr !== undefined && throughputIdx >= 0) fields[throughputIdx] = String(upd.newThroughputPerHr);
                    if (upd.newStatus !== undefined && statusIdx >= 0) fields[statusIdx] = upd.newStatus;
                    if (upd.newFreeGates !== undefined && freeGatesIdx >= 0) fields[freeGatesIdx] = String(upd.newFreeGates);
                    lines[i] = fields.join(',');
                  }
                }
                fs.writeFileSync(airportCsv, lines.join('\n'), 'utf8');
                results.push({ file: 'airport.csv', action: 'updated', airports: payload.airportUpdates.map((u) => u.airportId) });
              }

              const airportsJsonPath = path.join(projectRoot, 'data', 'airports.json');
              try {
                const airports = JSON.parse(fs.readFileSync(airportsJsonPath, 'utf8'));
                for (const upd of payload.airportUpdates) {
                  const airport = airports.find((a) => a.airportId === upd.airportId);
                  if (!airport) continue;
                  if (upd.newUtilizationPct !== undefined) airport.currentUtilizationPct = upd.newUtilizationPct;
                  if (upd.newThroughputPerHr !== undefined) airport.currentThroughputPerHr = upd.newThroughputPerHr;
                  if (upd.newStatus !== undefined) airport.status = upd.newStatus;
                  if (upd.newFreeGates !== undefined) airport.freeGates = upd.newFreeGates;
                }
                fs.writeFileSync(airportsJsonPath, `${JSON.stringify(airports, null, 2)}\n`, 'utf8');
                invalidate(airportsJsonPath);
                results.push({ file: 'airports.json', action: 'updated', airports: payload.airportUpdates.map((u) => u.airportId) });
              } catch (err) {
                results.push({ file: 'airports.json', action: 'error', error: err.message });
              }
            }

            res.end(JSON.stringify({ success: true, results }));
          })
          .catch((err) => {
            // eslint-disable-next-line no-console
            console.error('[flightops-writeback] action error:', err);
            res.statusCode = 500;
            res.end(JSON.stringify({ error: err.message }));
          });
      });
    },
  };
}
